28/B4DZq78ZWpJ4Bw-/0/1764089793356?e=2147483647&v=beta&t=4eEm9gg_SqrB2G9k_fNPx52MAIwxPWNnQEZxeSUb5Cc","https://dms.licdn.com/playlist/vid/v2/D4D05AQF-sMenRejecQ/mp4-720p-30fp-crf28/B4DZq78ZWpJ4CI-/0/1764089804917?e=2147483647&v=beta&t=XKr6Q_hxcjwCo5AI68hmyrk_ZOre_daMAQ6mrfXp5uA"]},{"date":"2025-12-12T12:41:45.980Z","images":["https://media.licdn.com/dms/image/v2/D4D22AQG4MDf8n-wB3Q/feedshare-shrink_800/B4DZr0D6u6IEAg-/0/1765031263803?e=2147483647&v=beta&t=9F-W4OhlSJ3JlqxPthANM2qYRRkPnYdgyUmuwPQoXAs","https://media.licdn.com/dms/image/v2/D4D22AQFjxl1-LKNUXg/feedshare-shrink_800/B4DZr0D6uTIAAg-/0/1765031261999?e=2147483647&v=beta&t=KuIPADe0PQW9WBXyjU4yHtB2tp8mD7fPvibi9nUrW70","https://media.licdn.com/dms/image/v2/D4D22AQEZiWgajQp8uA/feedshare-shrink_2048_1536/B4DZr0D6uvIAAw-/0/1765031265526?e=2147483647&v=beta&t=kCChLcpXqotRlLYP6rBfDU-F1jMeL8HaiMCDna1kpyE","https://media.licdn.com/dms/image/v2/D4D22AQG0wR77dUzG3g/feedshare-shrink_2048_1536/B4DZr0D6wmG4Aw-/0/1765031271156?e=2147483647&v=beta&t=u3brlpLjXfTaUS1dA3zZc5GnViL9GeFQfJdP-1kH_5M","https://media.licdn.com/dms/image/v2/D4D22AQEK9VadA8gYxQ/feedshare-shrink_2048_1536/B4DZr0D6u4IAAw-/0/1765031270406?e=2147483647&v=beta&t=cVwkiAOz2ldCADI0QO_8r7nH2uAkrqgac_dPTN0fyYU"],"likes_count":25,"post_id":"7403077700279586816","post_url":"https://www.linkedin.com/posts/oivan_finland108-oivanlife-suomi-activity-7403077700279586816-w_7H","repost":{"external_links":null,"images":null,"repost_date":null,"repost_followers":null,"repost_hangtags":null,"repost_id":null,"repost_text":null,"repost_title":null,"repost_url":null,"tagged_companies":null,"tagged_users":null,"videos":null},"tagged_companies":null,"tagged_people":null,"text":"Celebrating Finland’s 108th Independence Day in style! 🇫🇮 Thank you to the Embassy of Finland for hosting a lovely reception in Riyadh on last Wednesday. It was great to enjoy the evening and the festive atmosphere with Oivan colleagues. Tapio Äijälä , Aki Teliö , Waleed Altalib , Mohammad Ghnaim . Waleed Altalib , Tuukka Kaltiainen and Jouni Suutarinen #Finland108 #OivanLife #Suomi #Networking #Riyadh","text_html":"Celebrating Finland&#x2019;s 108th Independence Day in style! &#x1F1EB;&#x1F1EE;

Thank you to the Embassy of Finland for hosting a lovely reception in Riyadh on last Wednesday.

