<a class="link" href="https://www.linkedin.com/signup/cold-join?session_redirect=https%3A%2F%2Fwww.linkedin.com%2Ffeed%2Fhashtag%2Ftisco&amp;trk=organization_guest_main-feed-card-text" target="_self" data-tracking-control-name="organization_guest_main-feed-card-text" data-tracking-will-navigate>#TISCO</a>","time":"10mo","title":"TISCO Financial Group"},{"date":"2025-03-08T13:00:19.559Z","images":["https://media.licdn.com/dms/image/v2/D5622AQFHm4jvUAEkgw/feedshare-shrink_800/B56ZUcLOqoGUAg-/0/1739934461194?e=2147483647&v=beta&t=7k-u9W5yd3NJgk7Rv6QLBaNDpcCqjmcGWyITpWO0QRo","https://media.licdn.com/dms/image/v2/D5622AQG3OYvDozXOWQ/feedshare-shrink_800/B56ZUcLOrbGoAg-/0/1739934461377?e=2147483647&v=beta&t=iYshShM_e83Eb2LNgcemcNYRQ4_yNnferwJEQjnFqv8"],"likes_count":5,"post_id":"7297814079040012289","post_url":"https://th.linkedin.com/posts/tisco_%E0%B8%97%E0%B8%AA%E0%B9%82%E0%B8%81-%E0%B8%A3%E0%B8%A7%E0%B8%A1%E0%B8%81%E0%B8%9A-%E0%B8%A1%E0%B8%AB%E0%B8%B2%E0%B8%A7%E0%B8%97%E0%B8%A2%E0%B8%B2%E0%B8%A5%E0%B8%A2%E0%B8%81%E0%B8%A3%E0%B8%87%E0%B9%80%E0%B8%97%E0%B8%9E-%E0%B8%88%E0%B8%94%E0%B8%81%E0%B8%88%E0%B8%81%E0%B8%A3%E0%B8%A3%E0%B8%A1-activity-7297814079040012289-C-fe","repost":{"external_links":null,"images":null,"repost_date":null,"repost_followers":null,"repost_hangtags":null,"repost_id":null,"repost_text":null,"repost_title":null,"repost_url":null,"tagged_companies":null,"tagged_users":null,"videos":null},"tagged_companies":null,"tagged_people":null,"text":"ทิสโก้ ร่วมกับ มหาวิทยาลัยกรุงเทพ จัดกิจกรรม “ฉลาดเก็บ ฉลาดใช้ Content Creator” มุ่งเสริมสร้างความรู้ทางการเงินแก่นักศึกษามหาวิทยาลัย นำทีมโดย นางสาววิภา เมตตาวิหารี ผู้อำนวยการสายสินเชื่ออเนกประสงค์และการขายตรง นางสาวลดาวัลย์ ลีลาภรณ์ หัวหน้าธนกิจส่วนบุคคล และนางสาวศศิกานต์ กลึงเทศ หัวหน้าฝ่ายการตลาดดิจิทัลและพัฒนาลูกค้า พร้อมด้วย พ.ต.ท.ดร.ธนันวัฒน์ ธีรพัฒน์ชญากุล อาจารย์คณะตำรวจศาสตร์ โรงเรียนนายร้อยตำรวจ และ Content Creator ฉายา “มือปราบคอลเซ็นเตอร์” ซึ่งมาร่วมกันให้ความรู้ทางการเงินแก่นักศึกษาชั้นปีที่ 1-3 ในรูปแบบ Onsite และ Online โดยมี อาจารย์มณฑินี จักรสิรินนท์ ผู้อำนวยการหลักสูตรการวางแผนการเงินและการลงทุน คณะบริหารธุรกิจ และคณาจารย์มหาวิทยาลัยกรุงเทพ ให้การต้อนรับ ณ หอประชุม Diamond Hall มหาวิทยาลัยกรุงเทพ สำหรับกิจกรรม “ฉลาดเก็บ ฉลาดใช้ Content Creator” ออกแบบขึ้นเพื่อให้ความรู้ทางการเงินที่สำคัญใน 3 ด้าน ได้แก่ การวางแผนทางการเงิน การบริหารจัดการหนี้ และการป้องกันภัยทางการเงิน โดยภายหลังการอบรมเชิงปฏิบัติการยังมีการจัดประกวด “วิดีโอคอนเทนต์” เกี่ยวกับทักษะทางการเงินในรูปแบบต่าง ๆ พร้อมเงินรางวัลรวม 240,000 บาท มอบให้กับ 120 ผลงานที่ได้รับการคัดเลือกจากคณะกรรมการ นอกจากนี้ วิดีโอคอนเทนต์ที่ผลิตขึ้นจะนำไปเผยแพร่ผ่านช่องทางโซเชียลมีเดียของกลุ่มทิสโก้ เพื่อให้ประชาชนทั่วไปสามารถเข้าถึงความรู้ได้อย่างกว้างขวาง","text_html":"&#xE17;&#xE34;&#xE2A;&#xE42;&#xE01;&#xE49; &#xE23;&#xE48;&#xE27;&#xE21;&#xE01;&#xE31;&#xE1A; &#xE21;&#xE2B;&#xE32;&#xE27;&#xE34;&#xE17;&#xE22;&#xE32;&#xE25;&#xE31;&#xE22;&#xE01;&#xE23;&#xE38;&#xE07;&#xE40;&#xE17;&#xE1E; &#xE08;&#xE31;&#xE14;&#xE01;&#xE34;&#xE08;&#xE01;&#xE23;&#xE23;&#xE21;&#xA0;&#x201C;&#xE09;&#xE25;&#xE32;&#xE14;&#xE40;&#xE01;&#xE47;&#xE1A; &#xE09;&#xE25;&#xE32;&#xE14;&#xE43;&#xE0A;&#xE49; Content Creator&#x201D;&#xA0;&#xE21;&#xE38;&#xE48;&#xE07;&#xE40;&#xE2A;&#xE23;&#xE34;&#xE21;&#xE2A;&#xE23;&#xE49;&#xE32;&#xE07;&#xE04;&#xE27;&#xE32;&#xE21;&#xE23;&#xE39;&#xE49;&#xE17;&#xE32;&#xE07;&#xE01;&#xE32;&#xE23;&#xE40;&#xE07;&#xE34;&#xE19;&#xE41;&#xE01;&#xE48;&#xE19;&#xE31;&#xE01;&#xE28;&#xE36;&#xE01;&#xE29;&#xE32;&#xE21;&#xE2B;&#xE32;&#xE27;&#xE34;&#xE17;&#xE22;&#xE32;&#xE25;&#xE31;&#xE22; &#xE19;&#xE33;&#xE17;&#xE35;&#xE21;&#xE42;&#xE14;&#xE22;&#xA0;&#xE19;&#xE32;&#xE07;&#xE2A;&#xE32;&#xE27;&#xE27;&#xE34;&#xE20;&#xE32; &#xE40;&#xE21;&#xE15;&#xE15;&#xE32;&#xE27;&#xE34;&#xE2B;&#xE32;&#xE23;&#xE35;&#xA0;&#xE1C;&#xE39;&#xE49;&#xE2D;&#xE33;&#xE19;&#xE27;&#xE22;&#xE01;&#xE32;&#xE23;&#xE2A;&#xE32;&#xE22;&#xE2A;&#xE34;&#xE19;&#xE40;&#xE0A;&#xE37;&#xE48;&#xE2D;&#xE2D;&#xE40;&#xE19;&#xE01;&#xE1B;&#xE23;&#xE30;&#xE2A;&#xE07;&#xE04;&#xE4C;&#xE41;&#xE2