&#xE1E;.&#xE15;.&#xE17;.&#xE14;&#xE23;.&#xE18;&#xE19;&#xE31;&#xE19;&#xE27;&#xE31;&#xE12;&#xE19;&#xE4C; &#xE18;&#xE35;&#xE23;&#xE1E;&#xE31;&#xE12;&#xE19;&#xE4C;&#xE0A;&#xE0D;&#xE32;&#xE01;&#xE38;&#xE25;&#xA0;&#xE2D;&#xE32;&#xE08;&#xE32;&#xE23;&#xE22;&#xE4C;&#xE04;&#xE13;&#xE30;&#xE15;&#xE33;&#xE23;&#xE27;&#xE08;&#xE28;&#xE32;&#xE2A;&#xE15;&#xE23;&#xE4C; &#xE42;&#xE23;&#xE07;&#xE40;&#xE23;&#xE35;&#xE22;&#xE19;&#xE19;&#xE32;&#xE22;&#xE23;&#xE49;&#xE2D;&#xE22;&#xE15;&#xE33;&#xE23;&#xE27;&#xE08; &#xE41;&#xE25;&#xE30; Content Creator &#xE09;&#xE32;&#xE22;&#xE32;&#xA0;&#x201C;&#xE21;&#xE37;&#xE2D;&#xE1B;&#xE23;&#xE32;&#xE1A;&#xE04;&#xE2D;&#xE25;&#xE40;&#xE0B;&#xE47;&#xE19;&#xE40;&#xE15;&#xE2D;&#xE23;&#xE4C;&#x201D;&#xA0;&#xE01;&#xE25;&#xE48;&#xE32;&#xE27;&#xE27;&#xE48;&#xE32; &#xE17;&#xE38;&#xE01;&#xE04;&#xE19;&#xE40;&#xE1B;&#xE47;&#xE19;&#xE40;&#xE1B;&#xE49;&#xE32;&#xE2B;&#xE21;&#xE32;&#xE22;&#xE02;&#xE2D;&#xE07;&#xE21;&#xE34;&#xE08;&#xE09;&#xE32;&#xE0A;&#xE35;&#xE1E;&#xE2D;&#xE2D;&#xE19;&#xE44;&#xE25;&#xE19;&#xE4C; &#xE42;&#xE14;&#xE22;&#xE21;&#xE34;&#xE08;&#xE09;&#xE32;&#xE0A;&#xE35;&#xE1E;&#xE21;&#xE31;&#xE01;&#xE43;&#xE0A;&#xE49; 2 &#xE01;&#xE25;&#xE22;&#xE38;&#xE17;&#xE18;&#xE4C;&#xE40;&#xE1E;&#xE37;&#xE48;&#xE2D;&#xE2B;&#xE25;&#xE2D;&#xE01;&#xE25;&#xE27;&#xE07;&#xE1B;&#xE23;&#xE30;&#xE0A;&#xE32;&#xE0A;&#xE19; &#xE44;&#xE14;&#xE49;&#xE41;&#xE01;&#xE48; 1.&#xE01;&#xE32;&#xE23;&#xE2B;&#xE27;&#xE48;&#xE32;&#xE19;&#xE41;&#xE2B; &#xE04;&#xE37;&#xE2D;&#xE01;&#xE32;&#xE23;&#xE2A;&#xE48;&#xE07;&#xE02;&#xE49;&#xE2D;&#xE04;&#xE27;&#xE32;&#xE21;&#xE2B;&#xE25;&#xE2D;&#xE01;&#xE25;&#xE27;&#xE07;&#xE16;&#xE36;&#xE07;&#xE1A;&#xE38;&#xE04;&#xE04;&#xE25;&#xE17;&#xE31;&#xE48;&#xE27;&#xE44;&#xE1B; &#xE41;&#xE25;&#xE30; 2. &#xE01;&#xE32;&#xE23;&#xE1E;&#xE38;&#xE48;&#xE07;&#xE40;&#xE1B;&#xE49;&#xE32;&#xE2B;&#xE21;&#xE32;&#xE22;&#xE40;&#xE09;&#xE1E;&#xE32;&#xE30;&#xE1A;&#xE38;&#xE04;&#xE04;&#xE25; &#xE04;&#xE37;&#xE2D;&#xE01;&#xE32;&#xE23;&#xE2B;&#xE25;&#xE2D;&#xE01;&#xE25;&#xE48;&#xE2D;&