[{"date":"2026-01-01T08:45:58.887Z","likes_count":23,"post_id":"7412390454555463680","post_url":"https://www.linkedin.com/posts/netcare_to-our-patients-and-their-loved-ones-our-activity-7412390454555463680-pQzC","repost":{"external_links":null,"images":null,"repost_date":null,"repost_followers":null,"repost_hangtags":null,"repost_id":null,"repost_text":null,"repost_title":null,"repost_url":null,"tagged_companies":null,"tagged_users":null,"videos":null},"tagged_companies":null,"tagged_people":null,"text":"To our patients and their loved ones, our staff, doctors, and everyone we have the honour to work with, thank YOU for your trust and for being part of our journey. Here’s to 2026! 💙✨","text_html":"To our patients and their loved ones, our staff, doctors, and everyone we have the honour to work with, thank YOU for your trust and for being part of our journey. Here&#x2019;s to 2026!&#xA0;&#x1F499;&#x2728;","time":"1d","title":"Netcare","videos":["https://dms.licdn.com/playlist/vid/v2/D4D05AQH-zvcsAseC-g/mp4-640p-30fp-crf28/B4DZt4Z0RpH4B0-/0/1767251596651?e=2147483647&v=beta&t=jyxuJGpQ7IjZRA56f34Gu6uK8ZDyyfUnTkLmeM6luxY","https://dms.licdn.com/playlist/vid/v2/D4D05AQH-zvcsAseC-g/mp4-720p-30fp-crf28/B4DZt4Z0RpH4CM-/0/1767251596651?e=2147483647&v=beta&t=iPxB_eJyu0cMArNUlPpzknFy8a6qhGVDZ0FFZBRrn-A"]},{"comments_count":1,"date":"2025-12-26T08:45:58.890Z","images":["https://media.licdn.com/dms/image/v2/D5622AQGag0j_y2nmNg/feedshare-shrink_1280/B56ZtLkursHAAs-/0/1766499480950?e=2147483647&v=beta&t=G8khAqcZe64ymL01uxbqxoCzboz9y3rIuiEPdk7mICA"],"likes_count":45,"post_id":"7409235845523836928","post_url":"https://www.linkedin.com/posts/netcare_from-all-of-us-at-netcare-we-wish-you-and-activity-7409235845523836928-RdJ7","repost":{"external_links":null,"images":null,"repost_date":null,"repost_followers":null,"repost_hangtags":null,"repost_id":null,"repost_text":null,"repost_title":null,"repost_url":null,"tagged_companies":null,"tagged_users":null,"videos":null},"tagged_companies":null,"tagged_people":null,"text":"From all of us at Netcare, we wish YOU and your loved ones a safe, joyful, and healthy holiday season! 💙 Please note that we will not be responding to comments or messages from 23 December 2025 to 5 January 2026. 🚑 In case of a medical emergency, call Netcare 911 on 082 911 or download and register on the Netcare app today, and use the emergency button for instant geolocation and expert care in an emergency: https://lnkd.in/d9YnFRmw","text_html":"From all of us at Netcare, we wish YOU and your loved ones a safe, joyful, and healthy holiday season!&#xA0;&#x1F499;&#xA0;Please note that we will not be responding to comments or messages from 23 December 2025 to 5 January 2026.
