[{"comments_count":17,"date":"2025-12-30T13:58:24.988Z","likes_count":1882,"post_id":"7411697883596488704","post_url":"https://www.linkedin.com/posts/msc-mediterranean-shipping-co--s-a-_msccargo-activity-7411697883596488704-wXPl","repost":{"external_links":null,"images":null,"repost_date":null,"repost_followers":null,"repost_hangtags":null,"repost_id":null,"repost_text":null,"repost_title":null,"repost_url":null,"tagged_companies":null,"tagged_users":null,"videos":null},"tagged_companies":null,"tagged_people":null,"text":"A look back at some of the moments that shaped our year at MSC 🚢 💛 From trade events and a major celebration in Hamburg to complex project cargo moves, new partnerships and sporting events. And not to be forgotten, many picture-perfect moments at sea, in ports and ashore. We wish everyone a bright start to 2026! #msccargo","text_html":"A look back at some of the moments that shaped our year at MSC &#x1F6A2; &#x1F49B;

From trade events and a major celebration in Hamburg to complex project cargo moves, new partnerships and sporting events. And not to be forgotten, many picture-perfect moments at sea, in ports and ashore.

We wish everyone a bright start to 2026!

